import React, { createContext, useContext, useEffect, useMemo, useReducer } from 'react';

const StoreContext = createContext(null);

const STORAGE_KEYS = {
  cart: 'tech_store_cart',
  wishlist: 'tech_store_wishlist',
  user: 'tech_store_user',
  theme: 'tech_store_theme',
  recentSearches: 'tech_store_recent_searches',
  recentlyViewed: 'tech_store_recently_viewed',
};

const initialState = {
  cart: [],
  wishlist: [],
  user: null,
  theme: 'light',
  recentSearches: [],
  recentlyViewed: [],
  toast: null,
  authModal: {
    open: false,
    mode: 'login',
  },
};

function readStorage(key, fallback) {
  try {
    const saved = localStorage.getItem(key);
    return saved ? JSON.parse(saved) : fallback;
  } catch {
    return fallback;
  }
}

function writeStorage(key, value) {
  try {
    localStorage.setItem(key, JSON.stringify(value));
  } catch {
    /* localStorage can fail in private mode. UI should still work. */
  }
}

function getProductKey(product) {
  return String(product?.id || product?.productId || product?.externalId || product?.title || '');
}

function normalizeCartItem(product, quantity = 1) {
  const id = getProductKey(product);

  return {
    id,
    productId: id,
    title: product.title || 'Tech Product',
    brand: product.brand || 'Tech Brand',
    category: product.category || 'Technology',
    price: Number(product.price || 0),
    rating: Number(product.rating || 0),
    image: product.image || product.thumbnail || product.images?.[0] || '',
    stock: Number(product.stock || 99),
    availability: product.availability || 'In stock',
    quantity: Math.max(1, Number(quantity) || 1),
    source: product.source || 'dummyjson',
  };
}

function reducer(state, action) {
  switch (action.type) {
    case 'HYDRATE':
      return {
        ...state,
        ...action.payload,
      };

    case 'SET_THEME':
      return {
        ...state,
        theme: action.payload,
      };

    case 'TOAST':
      return {
        ...state,
        toast: action.payload,
      };

    case 'CLEAR_TOAST':
      return {
        ...state,
        toast: null,
      };

    case 'OPEN_AUTH':
      return {
        ...state,
        authModal: {
          open: true,
          mode: action.payload || 'login',
        },
      };

    case 'CLOSE_AUTH':
      return {
        ...state,
        authModal: {
          ...state.authModal,
          open: false,
        },
      };

    case 'SET_AUTH_MODE':
      return {
        ...state,
        authModal: {
          ...state.authModal,
          mode: action.payload,
        },
      };

    case 'LOGIN':
      return {
        ...state,
        user: action.payload,
        authModal: {
          ...state.authModal,
          open: false,
        },
      };

    case 'LOGOUT':
      return {
        ...state,
        user: null,
      };

    case 'ADD_TO_CART': {
      const item = normalizeCartItem(action.payload.product, action.payload.quantity);
      const exists = state.cart.find((cartItem) => cartItem.id === item.id);

      if (exists) {
        return {
          ...state,
          cart: state.cart.map((cartItem) =>
            cartItem.id === item.id
              ? {
                  ...cartItem,
                  quantity: Math.min(cartItem.quantity + item.quantity, cartItem.stock || 99),
                }
              : cartItem
          ),
        };
      }

      return {
        ...state,
        cart: [...state.cart, item],
      };
    }

    case 'REMOVE_FROM_CART':
      return {
        ...state,
        cart: state.cart.filter((item) => item.id !== action.payload),
      };

    case 'UPDATE_CART_QUANTITY':
      return {
        ...state,
        cart: state.cart.map((item) =>
          item.id === action.payload.id
            ? {
                ...item,
                quantity: Math.max(1, Math.min(Number(action.payload.quantity) || 1, item.stock || 99)),
              }
            : item
        ),
      };

    case 'CLEAR_CART':
      return {
        ...state,
        cart: [],
      };

    case 'TOGGLE_WISHLIST': {
      const product = action.payload;
      const id = getProductKey(product);
      const exists = state.wishlist.some((item) => getProductKey(item) === id);

      if (exists) {
        return {
          ...state,
          wishlist: state.wishlist.filter((item) => getProductKey(item) !== id),
        };
      }

      return {
        ...state,
        wishlist: [
          ...state.wishlist,
          {
            ...product,
            id,
            productId: id,
          },
        ],
      };
    }

    case 'REMOVE_WISHLIST':
      return {
        ...state,
        wishlist: state.wishlist.filter((item) => getProductKey(item) !== action.payload),
      };

    case 'ADD_RECENT_SEARCH': {
      const value = String(action.payload || '').trim();

      if (!value) {
        return state;
      }

      const next = [value, ...state.recentSearches.filter((item) => item.toLowerCase() !== value.toLowerCase())].slice(0, 8);

      return {
        ...state,
        recentSearches: next,
      };
    }

    case 'ADD_RECENTLY_VIEWED': {
      const product = action.payload;

      if (!product) {
        return state;
      }

      const id = getProductKey(product);
      const next = [
        {
          ...product,
          id,
          productId: id,
        },
        ...state.recentlyViewed.filter((item) => getProductKey(item) !== id),
      ].slice(0, 8);

      return {
        ...state,
        recentlyViewed: next,
      };
    }

    default:
      return state;
  }
}

export function StoreProvider({ children }) {
  const [state, dispatch] = useReducer(reducer, initialState);

  useEffect(() => {
    const savedTheme = readStorage(STORAGE_KEYS.theme, 'light');

    dispatch({
      type: 'HYDRATE',
      payload: {
        cart: readStorage(STORAGE_KEYS.cart, []),
        wishlist: readStorage(STORAGE_KEYS.wishlist, []),
        user: readStorage(STORAGE_KEYS.user, null),
        theme: savedTheme,
        recentSearches: readStorage(STORAGE_KEYS.recentSearches, []),
        recentlyViewed: readStorage(STORAGE_KEYS.recentlyViewed, []),
      },
    });

    document.documentElement.setAttribute('data-theme', savedTheme);
  }, []);

  useEffect(() => {
    writeStorage(STORAGE_KEYS.cart, state.cart);
  }, [state.cart]);

  useEffect(() => {
    writeStorage(STORAGE_KEYS.wishlist, state.wishlist);
  }, [state.wishlist]);

  useEffect(() => {
    writeStorage(STORAGE_KEYS.user, state.user);
  }, [state.user]);

  useEffect(() => {
    writeStorage(STORAGE_KEYS.theme, state.theme);
    document.documentElement.setAttribute('data-theme', state.theme);
  }, [state.theme]);

  useEffect(() => {
    writeStorage(STORAGE_KEYS.recentSearches, state.recentSearches);
  }, [state.recentSearches]);

  useEffect(() => {
    writeStorage(STORAGE_KEYS.recentlyViewed, state.recentlyViewed);
  }, [state.recentlyViewed]);

  useEffect(() => {
    if (!state.toast) {
      return undefined;
    }

    const timer = setTimeout(() => {
      dispatch({ type: 'CLEAR_TOAST' });
    }, 3000);

    return () => clearTimeout(timer);
  }, [state.toast]);

  const cartCount = useMemo(
    () => state.cart.reduce((total, item) => total + Number(item.quantity || 0), 0),
    [state.cart]
  );

  const cartSubtotal = useMemo(
    () => state.cart.reduce((total, item) => total + Number(item.price || 0) * Number(item.quantity || 1), 0),
    [state.cart]
  );

  const wishlistCount = state.wishlist.length;

  const showToast = (message, type = 'success') => {
    dispatch({
      type: 'TOAST',
      payload: {
        message,
        type,
        id: Date.now(),
      },
    });
  };

  const addToCart = (product, quantity = 1) => {
    dispatch({
      type: 'ADD_TO_CART',
      payload: {
        product,
        quantity,
      },
    });

    showToast(`${product?.title || 'Product'} added to cart`, 'success');
  };

  const removeFromCart = (id) => {
    dispatch({
      type: 'REMOVE_FROM_CART',
      payload: id,
    });

    showToast('Product removed from cart', 'info');
  };

  const updateCartQuantity = (id, quantity) => {
    dispatch({
      type: 'UPDATE_CART_QUANTITY',
      payload: {
        id,
        quantity,
      },
    });
  };

  const clearCart = () => {
    dispatch({
      type: 'CLEAR_CART',
    });

    showToast('Cart cleared successfully', 'info');
  };

  const toggleWishlist = (product) => {
    const id = getProductKey(product);
    const alreadySaved = state.wishlist.some((item) => getProductKey(item) === id);

    dispatch({
      type: 'TOGGLE_WISHLIST',
      payload: product,
    });

    showToast(alreadySaved ? 'Removed from wishlist' : 'Added to wishlist', alreadySaved ? 'info' : 'success');
  };

  const isInWishlist = (productOrId) => {
    const id = typeof productOrId === 'string' ? productOrId : getProductKey(productOrId);
    return state.wishlist.some((item) => getProductKey(item) === id);
  };

  const moveWishlistToCart = (product) => {
    addToCart(product, 1);
    dispatch({
      type: 'REMOVE_WISHLIST',
      payload: getProductKey(product),
    });
  };

  const login = (payload) => {
    const user = {
      id: payload?.id || 'user_001',
      name: payload?.name || payload?.fullName || 'Tech Store User',
      email: payload?.email || 'user@techstore.com',
      role: payload?.role || 'user',
      avatar: payload?.avatar || '',
    };

    dispatch({
      type: 'LOGIN',
      payload: user,
    });

    showToast(`Welcome back, ${user.name}`, 'success');
  };

  const signup = (payload) => {
    const user = {
      id: `user_${Date.now()}`,
      name: payload?.name || payload?.fullName || 'New User',
      email: payload?.email || 'user@techstore.com',
      role: 'user',
      avatar: '',
    };

    dispatch({
      type: 'LOGIN',
      payload: user,
    });

    showToast('Account created successfully', 'success');
  };

  const logout = () => {
    dispatch({
      type: 'LOGOUT',
    });

    showToast('Logged out successfully', 'info');
  };

  const openAuth = (mode = 'login') => {
    dispatch({
      type: 'OPEN_AUTH',
      payload: mode,
    });
  };

  const closeAuth = () => {
    dispatch({
      type: 'CLOSE_AUTH',
    });
  };

  const setAuthMode = (mode) => {
    dispatch({
      type: 'SET_AUTH_MODE',
      payload: mode,
    });
  };

  const toggleTheme = () => {
    dispatch({
      type: 'SET_THEME',
      payload: state.theme === 'dark' ? 'light' : 'dark',
    });
  };

  const addRecentSearch = (query) => {
    dispatch({
      type: 'ADD_RECENT_SEARCH',
      payload: query,
    });
  };

  const addRecentlyViewed = (product) => {
    dispatch({
      type: 'ADD_RECENTLY_VIEWED',
      payload: product,
    });
  };

  const value = {
    ...state,
    cartCount,
    cartSubtotal,
    wishlistCount,
    addToCart,
    removeFromCart,
    updateCartQuantity,
    clearCart,
    toggleWishlist,
    isInWishlist,
    moveWishlistToCart,
    login,
    signup,
    logout,
    openAuth,
    closeAuth,
    setAuthMode,
    toggleTheme,
    showToast,
    addRecentSearch,
    addRecentlyViewed,
  };

  return <StoreContext.Provider value={value}>{children}</StoreContext.Provider>;
}

export function useStore() {
  const context = useContext(StoreContext);

  if (!context) {
    throw new Error('useStore must be used inside StoreProvider');
  }

  return context;
}

export default StoreContext;
